PreparedSource prepareMxf(QIODevice &input, const SourceCandidate &candidate,
						  const QString &readReason, const Cancellation &cancellation)
{

	PreparedSource prepareMxf(const SourceCandidate &candidate, const QString &readReason,
							  const Cancellation &cancellation)
	{
		requireMxf(candidate);
		QFile input(candidate.path);
		if (cancellation.cancelled())
			return prepareMxf(input, candidate, readReason, cancellation);
		if (input.open(QIODevice::ReadOnly))
			return readMxf(input, candidate, readReason, cancellation);
		ParsedSource parsed;
		auto snapshot = inputReceipt(candidate);
		parsed.snapshot = snapshot;
		parsed.readReason = readReason;
		// Cancellation during a failed open does not erase the filesystem failure
		// that this scan actually obtained.
		snapshot->readState = SourceReadState::Unreadable;
		parsed.outcome = ParsedSource::Outcome::IoError;
		parsed.diagnostics.append(input.errorString());
		return {{}, SourceReceipt::fromParsed(std::move(parsed))};
	}
}

Decoded utf16(QByteArrayView bytes, bool bigEndian)
{
	Decoded result;
	result.text = bigEndian ? TextEncoding::Utf16BE : TextEncoding::Utf16LE;
	if (bytes.size() % 2)
	{
		result.valid = false;
		result.explanation = QStringLiteral("UTF-16 has an incomplete two-byte code unit.");
		return result;
	}
	QString text;
	text.reserve(bytes.size() / 2);
	bool pendingHigh = false;
	for (qsizetype offset = 0; offset < bytes.size(); offset += 2)
	{
		const char *at = bytes.data() + offset;
		const quint16 unit = bigEndian ? qFromBigEndian<quint16>(at) : qFromLittleEndian<quint16>(at);
		if (!unit)
			break;
		const bool high = unit >= 0xd800 && unit <= 0xdbff;
		const bool low = unit >= 0xdc00 && unit <= 0xdfff;
		if ((pendingHigh && !low) || (low && !pendingHigh))
		{
			result.valid = false;
			break;
		}
		pendingHigh = high;
		text.append(QChar(unit));
	}
	result.valid = result.valid && !pendingHigh;
	if (result.valid)
	{
		result.value = text;
		result.explanation = QStringLiteral("UTF-16 text ends at the first null code unit; original terminator and any padding remain in the encoded value.");
	}
	else
		result.explanation = QStringLiteral("UTF-16 has an unpaired surrogate; original bytes are retained.");
	return result;
}

