void discoverRoots()
{
	QHash<qint64, QVector<const AvidObject *>> partitions;
	for (const auto &object : m_source.objects)
		if (object.mxf)
		{
			auto &prefaces = partitions[object.mxf->partitionOffset];
			if (isClass(object, "Preface"))
